182	struct CommissionWorkCtx {
183	    uint32_t passcode;
184	    uint32_t discriminator;
185	    chip::NodeId node_id;
186	    char     address[46];   /* commissionable IPv6 from the phone; "" = discover */
187	    uint16_t port;
188	};
