604	/* ── Handler: POST /commission ───────────────────────────────────────────── */
605	/* Commission-then-handoff (see flux_commission.h / docs/multiadmin-rework.md).
606	 * The phone has already BLE-commissioned the device onto a throwaway fabric and
607	 * opened an ECM commissioning window; it hands us the window's passcode +
608	 * discriminator and we commission the device onto our own fabric directly. */
609	
610	/* Commissioning can take up to ~2 min (PASE + AddNOC + the device's Thread
611	 * router promotion + the operational CASE for CommissioningComplete). Blocking
612	 * the single CoAP task that long would stall every other request and force the
613	 * client to retransmit (each retransmit spawning a duplicate commission). So we
614	 * use a CoAP **separate response**: the handler returns an empty ACK immediately
615	 * (libcoap does this when the response code is left at 0), a worker task runs the
616	 * blocking commission off the CoAP task, and the real reply is sent later from
617	 * the notify-queue drain (flux_coap_drain_notify_queue), on the CoAP task. */
618	typedef struct {
619	    coap_session_t *session;   /* referenced; released when the reply is sent  */
620	    uint8_t  token[8];
621	    size_t   token_len;
622	    uint32_t passcode;
623	    uint32_t discriminator;
624	    uint64_t req_node_id;
625	    char     device_address[46];
626	    uint32_t device_port;
627	    uint32_t vendor_id;
628	    uint32_t product_id;
629	    uint32_t device_type;
630	    char     name[40];
631	} commission_job_t;
632	
633	static void commission_worker(void *arg)
634	{
635	    commission_job_t *job = (commission_job_t *)arg;
636	
637	    uint64_t node_id = 0, fabric_id = 0;
638	    char     error_buf[160] = "";
639	    esp_err_t err = flux_commission_device(
640	        job->passcode, job->discriminator, job->req_node_id,
641	        job->device_address, (uint16_t)job->device_port,
642	        &node_id, &fabric_id, error_buf, sizeof(error_buf));
643	
644	    notify_t *n = (notify_t *)calloc(1, sizeof(notify_t));
645	    if (n) {
646	        n->type          = NOTIFY_TYPE_COMMISSION_RESULT;
647	        n->cm_session    = job->session;
648	        n->cm_token_len  = job->token_len;
649	        if (job->token_len) memcpy(n->cm_token, job->token, job->token_len);
650	        n->cm_success    = (err == ESP_OK);
651	        n->node_id       = node_id;
652	        n->cm_fabric_id  = fabric_id;
653	        n->cm_vendor_id  = job->vendor_id;
654	        n->cm_product_id = job->product_id;
655	        n->cm_device_type= job->device_type;
656	        if (job->name[0] != '\0')
657	            snprintf(n->cm_name, sizeof(n->cm_name), "%s", job->name);
658	        else
659	            snprintf(n->cm_name, sizeof(n->cm_name), "Device %04llX",
660	                     (unsigned long long)(node_id & 0xFFFF));
661	        if (err != ESP_OK)
662	            snprintf(n->cm_error, sizeof(n->cm_error), "%s", error_buf);
663	
664	        if (xQueueSend(flux_coap_notify_queue, &n, 0) != pdTRUE) {
665	            /* Queue full (≈never): the deferred reply is lost and the session
666	             * ref leaks (coap_session_release must run on the CoAP task). The
667	             * app times out and retries; the controller cache then replays. */
668	            ESP_LOGW(TAG, "notify queue full — dropping commission reply for %016llx",
669	                     (unsigned long long)node_id);
670	            free(n);
671	        }
672	    } else {
673	        ESP_LOGE(TAG, "oom building commission reply");
674	    }
675	
676	    free(job);
677	    vTaskDelete(NULL);
678	}
