/* The controller has no local PAA trust store. The phone already performed
 * full DAC/PAA attestation during its Pass-1 BLE commissioning, so the
 * controller's own commissioning pass does not need to repeat that check. */

struct CommissionCtx {
    uint32_t passcode;
    uint16_t discriminator;   /* filtered client-side in OnDiscoveredDevice */
    chip::NodeId node_id;
    char     error[256];
    bool     ok;
    flux_async_t async;       /* bounded wait + abandonment + single-owner free */
};
CommissionCtx *s_ctx = nullptr;

/* Idempotency cache. A /commission request is not idempotent but can legitimately
 * be repeated (CoAP retransmit while the long commission is in flight, app resend,
 * user re-scan). Re-running PASE against a device whose ECM window has since closed
 * fails and masks the original success. Remember the last successful commission for
 * a short window and replay its result for a repeated request to the same address. */
constexpr int64_t kCommissionCacheTtlUs = 30 * 1000 * 1000; /* 30 s */
struct LastCommission {
    char     address[46];
    uint64_t node_id;
    uint64_t fabric_id;
    int64_t  when_us;  /* esp_timer_get_time() at success; 0 = none cached */
};
LastCommission s_last = {};

