/* Discriminator match for both lookup paths. A manual 11-digit pairing code
 * only carries the 4-bit short discriminator (upper nibble of the full 12-bit
 * value), so match on longDisc >> 8 when the request says so. */
bool disc_matches(uint16_t long_disc)
{
    if (!s_ctx) return false;
    return s_ctx->short_disc ? ((long_disc >> 8) & 0xF) == (s_ctx->discriminator & 0xF)
                             : long_disc == s_ctx->discriminator;
}

