class FluxCommissionDelegate : public chip::Controller::DevicePairingDelegate,
                                public chip::Controller::DeviceDiscoveryDelegate {
public:
    void OnDiscoveredDevice(const chip::Dnssd::CommissionNodeData &nodeData) override
    {
        if (!s_ctx) return;
        ESP_LOGI(TAG, "OnDiscoveredDevice: disc=%u cm=%u",
                 (unsigned)nodeData.longDiscriminator, (unsigned)nodeData.commissioningMode);
        /* We browse all commissionable nodes (kNone) and match the window
         * discriminator the phone gave us. Two things the OTBR's SRP->mDNS proxy
         * breaks: (1) it omits the L<disc> subtype PTR, so kLongDiscriminator
         * discovery never matches; (2) it drops the CM (commissioning-mode) flag,
         * so discovered records look like CM=0. We therefore do NOT gate on
         * commissioningMode — the phone just opened the ECM window with this exact
         * discriminator, so a discriminator match is the reliable signal. */
        if (nodeData.longDiscriminator != s_ctx->discriminator) return;

        auto &ci = matter_controller_client::get_instance();
        ci.get_commissioner()->RegisterDeviceDiscoveryDelegate(nullptr);

        char addr_buf[chip::Inet::IPAddress::kMaxStringLength];
        nodeData.ipAddress[0].ToString(addr_buf);
        ESP_LOGI(TAG, "discovered device: %s:%u", addr_buf, nodeData.port);

        chip::Inet::InterfaceId ifc =
            nodeData.ipAddress[0].IsIPv6LinkLocal() ? nodeData.interfaceId : chip::Inet::InterfaceId::Null();
        chip::Transport::PeerAddress peer =
            chip::Transport::PeerAddress::UDP(nodeData.ipAddress[0], nodeData.port, ifc);
        chip::RendezvousParameters params =
            chip::RendezvousParameters().SetSetupPINCode(s_ctx->passcode).SetPeerAddress(peer);
        chip::Controller::CommissioningParameters commissioning_params;
        commissioning_params.SetDeviceAttestationDelegate(&s_attest_delegate);

