/* TXT data is a sequence of length-prefixed strings ("D=3840", "CM=2", …).
 * Extract the D= (long discriminator) entry. */
bool txt_find_discriminator(const uint8_t *txt, uint16_t len, uint16_t *out_disc)
{
    uint16_t i = 0;
    while (i < len) {
        uint8_t l = txt[i++];
        if (l == 0 || (uint16_t)(i + l) > len) break;
        if (l > 2 && txt[i] == 'D' && txt[i + 1] == '=') {
            char buf[8] = {};
            uint8_t n = (uint8_t)(l - 2);
            if (n > sizeof(buf) - 1) n = sizeof(buf) - 1;
            memcpy(buf, &txt[i + 2], n);
            *out_disc = (uint16_t)atoi(buf);
            return true;
        }
        i = (uint16_t)(i + l);
    }
    return false;
}

/* Look for the device in our own SRP server table — the authoritative source
 * for devices on our Thread mesh (their _matterc._udp window registration
 * carries the full TXT that the SRP->mDNS advertising proxy strips). Runs on
 * the CHIP task; takes the OT lock briefly. Returns true if PASE was started. */
bool try_srp_commission()
{
    if (!s_ctx || s_ctx->pase_started) return false;
    if (!esp_openthread_lock_acquire(pdMS_TO_TICKS(200))) return false;

    otInstance *ot = esp_openthread_get_instance();
    char     addr_str[OT_IP6_ADDRESS_STRING_SIZE] = "";
    uint16_t port  = 0;
    bool     found = false;

    for (const otSrpServerHost *host = otSrpServerGetNextHost(ot, nullptr);
         host != nullptr && !found; host = otSrpServerGetNextHost(ot, host)) {
        if (otSrpServerHostIsDeleted(host)) continue;
        for (const otSrpServerService *svc = otSrpServerHostGetNextService(host, nullptr);
             svc != nullptr; svc = otSrpServerHostGetNextService(host, svc)) {
            if (otSrpServerServiceIsDeleted(svc)) continue;
            const char *sname = otSrpServerServiceGetServiceName(svc);
            if (sname == nullptr || strncasecmp(sname, "_matterc._udp", 13) != 0) continue;

            uint16_t txt_len = 0, disc = 0;
            const uint8_t *txt = otSrpServerServiceGetTxtData(svc, &txt_len);
            if (txt == nullptr || !txt_find_discriminator(txt, txt_len, &disc)) continue;
            if (!disc_matches(disc)) continue;

            uint8_t n_addr = 0;
            const otIp6Address *addrs = otSrpServerHostGetAddresses(host, &n_addr);
            if (addrs == nullptr || n_addr == 0) continue;

            /* Prefer a routable (OMR) address over the mesh-local EID; both
             * work from the border router itself, but OMR matches what the
             * operational session will use later. */
            const otMeshLocalPrefix *ml = otThreadGetMeshLocalPrefix(ot);
            const otIp6Address *pick = &addrs[0];
            for (uint8_t k = 0; k < n_addr; k++) {
                if (ml != nullptr && memcmp(addrs[k].mFields.m8, ml->m8, sizeof(ml->m8)) == 0)
                    continue;                     /* mesh-local — keep looking */
                pick = &addrs[k];
                break;
            }
            otIp6AddressToString(pick, addr_str, sizeof(addr_str));
            port  = otSrpServerServiceGetPort(svc);
            found = true;
            ESP_LOGI(TAG, "matched SRP registration %s disc=%u -> [%s]:%u",
                     sname, (unsigned)disc, addr_str, (unsigned)port);
            break;
        }
    }
    esp_openthread_lock_release();

    if (!found) return false;

    chip::Inet::IPAddress addr;
    if (!chip::Inet::IPAddress::FromString(addr_str, addr)) {
        ESP_LOGW(TAG, "SRP address parse failed: %s", addr_str);
        return false;
    }
    start_pase(chip::Transport::PeerAddress::UDP(addr, port ? port : 5540,
                                                 chip::Inet::InterfaceId::Null()));
    return true;
}

/* Re-poll the SRP table while the mDNS browse runs — the device's window
 * registration can land via SRP moments after the /commission request. */
void srp_poll_cb(chip::System::Layer *layer, void *app_state)
{
    if (!s_ctx || s_ctx->pase_started) return;
    if (try_srp_commission()) return;
    chip::DeviceLayer::SystemLayer().StartTimer(
        chip::System::Clock::Milliseconds32(2000), srp_poll_cb, nullptr);
}

