578	  // ── Name generation ───────────────────────────────────────────────────────
579	
580	  String _generateName(List<String> existing) {
581	    final base = parsed?.suggestedName ?? 'Matter Device';
582	    if (!existing.contains(base)) return base;
583	    for (var i = 2; i <= 99; i++) {
584	      final candidate = '$base $i';
585	      if (!existing.contains(candidate)) return candidate;
586	    }
587	    return '$base ${DateTime.now().millisecondsSinceEpoch}';
588	  }
