/* Fires after every AutoCommissioner stage — streamed to the app via the
 * observable GET /commission/events so the progress track advances while
 * the controller commissions. Stage names (StageToString) are the same
 * ones the phone SDK reports, so the app maps them with its existing
 * stage table. Advisory only; failures are finalized by the delegates. */
void OnCommissioningStatusUpdate(chip::PeerId peerId,
                                 chip::Controller::CommissioningStage stageCompleted,
                                 CHIP_ERROR error) override
{
    const char *stage = chip::Controller::StageToString(stageCompleted);
    if (error != CHIP_NO_ERROR) {
        flux_events_emit_commission(stage, true, error.AsString());
    } else {
        flux_events_emit_commission(stage, false, nullptr);
    }
}

