11	  /// Decodes all recognised fields.  Returns an empty list on error or when
12	  /// [hex] is empty (e.g. the "Empty dataset" option).
13	  static List<({String label, String value})> decode(String hex) {
14	    final clean = hex.replaceAll(RegExp(r'\s'), '');
15	    if (clean.length < 4 || clean.length.isOdd) return [];
16	
17	    final bytes = <int>[];
18	    for (var i = 0; i + 1 < clean.length; i += 2) {
19	      bytes.add(int.parse(clean.substring(i, i + 2), radix: 16));
20	    }
21	
22	    final tlvs = <int, List<int>>{};
23	    var i = 0;
24	    while (i + 1 < bytes.length) {
25	      final type = bytes[i];
26	      final len = bytes[i + 1];
27	      if (i + 2 + len > bytes.length) break;
28	      tlvs[type] = bytes.sublist(i + 2, i + 2 + len);
29	      i += 2 + len;
30	    }
31	
32	    final out = <({String label, String value})>[];
33	    void add(String label, String value) => out.add((label: label, value: value));
34	
35	    // 1. Network Name (0x03)
36	    if (tlvs.containsKey(0x03)) add('Network Name', String.fromCharCodes(tlvs[0x03]!));
37	
38	    // 2. Network Key (0x05)
39	    if (tlvs.containsKey(0x05)) add('Network Key', _hex(tlvs[0x05]!));
40	
41	    // 3. Channel (0x00) + Channel Page
42	    if (tlvs.containsKey(0x00)) {
43	      final v = tlvs[0x00]!;
44	      if (v.length >= 3) {
45	        add('Channel', '${(v[1] << 8) | v[2]}');
46	        add('Channel Page', '${v[0]}');
47	      }
48	    }
49	
50	    // 4. Channel Mask (0x35)
51	    if (tlvs.containsKey(0x35)) {
52	      final v = tlvs[0x35]!;
53	      if (v.length >= 2) {
54	        final page = v[0];
55	        final maskLen = v[1];
56	        if (v.length >= 2 + maskLen) {
57	          add('Channel Masks', '{Page: $page, Mask: ${_hex(v.sublist(2, 2 + maskLen)).toUpperCase()}}');
58	        }
59	      }
60	    }
61	
62	    // 5. PAN ID (0x01)
63	    if (tlvs.containsKey(0x01)) {
64	      final v = tlvs[0x01]!;
65	      if (v.length >= 2) add('PAN ID', '${(v[0] << 8) | v[1]}');
66	    }
67	
68	    // 6. Extended PAN ID (0x02)
69	    if (tlvs.containsKey(0x02)) add('Ext PAN ID', _hex(tlvs[0x02]!));
70	
71	    // 7. Mesh-Local Prefix (0x07)
72	    if (tlvs.containsKey(0x07)) add('Mesh Local Prefix', _hex(tlvs[0x07]!));
73	
74	    // 8. PSKc (0x04)
75	    if (tlvs.containsKey(0x04)) add('PSKc', _hex(tlvs[0x04]!));
76	
77	    // 9. Security Policy (0x0C)
78	    if (tlvs.containsKey(0x0C)) {
79	      final v = tlvs[0x0C]!;
80	      if (v.length >= 4) {
81	        add('Security Policy', '{Rotation: ${(v[0] << 8) | v[1]}h, Flags: ${_hexUpper(v.sublist(2, 4))}}');
82	      }
83	    }
84	
85	    // 10. Active Timestamp (0x0E)
86	    if (tlvs.containsKey(0x0E)) {
87	      final v = tlvs[0x0E]!;
88	      if (v.length >= 8) {
89	        var secs = 0;
90	        for (var j = 0; j < 6; j++) {
91	          secs = (secs << 8) | v[j];
92	        }
93	        final last2 = (v[6] << 8) | v[7];
94	        add('Active Timestamp', '{Seconds: $secs, Ticks: ${last2 >> 1}, IsAuthoritativeSource: ${(last2 & 1) == 1}}');
95	      }
96	    }
97	
98	    // 11. Pending Timestamp (0x0F)
99	    if (tlvs.containsKey(0x0F)) {
100	      final v = tlvs[0x0F]!;
101	      if (v.length >= 8) {
102	        var secs = 0;
103	        for (var j = 0; j < 6; j++) {
104	          secs = (secs << 8) | v[j];
105	        }
106	        add('Pending Timestamp', 'Seconds: $secs');
107	      }
108	    }
109	
110	    return out;
111	  }
