226	  @override
227	  void paint(Canvas canvas, Size size) {
228	    final pts = prices.points;
229	    if (pts.isEmpty) return;
230	
231	    final plotH = size.height - _padBottom - _padTop;
232	    final plotW = size.width - _padLeft;
233	
234	    final resMs = prices.resolution.inMilliseconds;
235	    final coverStart = pts.first.time.millisecondsSinceEpoch;
236	    final coverEnd = pts.last.time.millisecondsSinceEpoch + resMs;
237	
238	    // Window to ~now ±12h so past consumption and upcoming prices share the view.
239	    const half = 12 * 3600 * 1000;
240	    final nowMs = now.millisecondsSinceEpoch;
241	    var startMs = nowMs - half < coverStart ? coverStart : nowMs - half;
242	    var endMs = nowMs + half > coverEnd ? coverEnd : nowMs + half;
243	    if (endMs <= startMs) { startMs = coverStart; endMs = coverEnd; }
244	    final span = (endMs - startMs).toDouble();
245	    double x(int ms) => _padLeft + plotW * (ms - startMs) / span;
246	
247	    // Price Y scale — include 0, round the top (and bottom, if negative) to a
248	    // nice value so the gridline labels are tidy.
249	    final rawHi = prices.maxCt > 0 ? prices.maxCt : 1.0;
250	    final rawLo = prices.minCt < 0 ? prices.minCt : 0.0;
251	    final step = _niceStep((rawHi - rawLo) / 4);
252	    final hi = (rawHi / step).ceil() * step;
253	    final lo = (rawLo / step).floor() * step;
254	    final range = (hi - lo) <= 0 ? 1.0 : (hi - lo);
255	    double yPrice(double ct) => _padTop + plotH * (1 - (ct - lo) / range);
