1	import 'package:flutter/foundation.dart';
2	import 'package:matter_home/models/energy_history.dart';
3	import 'package:matter_home/services/proto/flux.pb.dart' as $proto;
4	import 'package:matter_home/services/proto/flux.pbenum.dart' as $enum;
5	
6	/// One price interval: its start time and the price in ct/kWh (may be negative —
7	/// day-ahead spot prices can go below zero).
8	@immutable
9	class PricePoint {
10	  const PricePoint({required this.time, required this.ctPerKwh});
11	  final DateTime time;
12	  final double ctPerKwh;
13	}
14	
15	/// Decoded day-ahead price curve: per-interval ct/kWh plus the min/max/avg for
16	/// the covered window. Built from [$proto.PriceCurve]; the UI never sees raw
17	/// protobuf. Prices are the wholesale spot curve.
18	@immutable
19	class EnergyPrices {
20	  const EnergyPrices({
21	    required this.points,
22	    required this.resolution,
23	    required this.currency,
24	    required this.stale,
25	    required this.minCt,
26	    required this.maxCt,
27	    required this.avgCt,
28	  });
29	
30	  final List<PricePoint> points;
31	  final Duration resolution;
32	  final String currency;
33	  final bool stale;
34	  final double minCt;
35	  final double maxCt;
36	  final double avgCt;
37	
38	  bool get isEmpty => points.isEmpty;
39	
40	  /// The interval covering [now], or null if outside coverage.
41	  PricePoint? currentAt(DateTime now) {
42	    for (final p in points) {
43	      if (!now.isBefore(p.time) && now.isBefore(p.time.add(resolution))) return p;
44	    }
45	    return null;
46	  }
47	
48	  /// Cost (in cents) of the energy imported from the grid in [history], each
49	  /// bucket valued at the (gross) price covering its time. This is what the user
50	  /// actually pays. Null when there's no overlap with price coverage.
51	  double? importCostCents(EnergyHistoryData? history) {
52	    if (history == null || history.points.isEmpty || points.isEmpty) return null;
53	    final bucketHours = history.bucket.inSeconds / 3600.0;
54	    var cents = 0.0;
55	    var any = false;
56	    for (final p in history.points) {
57	      final price = currentAt(p.time);
58	      if (price == null) continue; // spot varies by hour → only where priced
59	      cents += p.gridImportW * bucketHours / 1000.0 * price.ctPerKwh;
60	      any = true;
61	    }
62	    return any ? cents : null;
63	  }
64	
65	  /// Revenue (in cents) from energy exported to the grid over the whole
66	  /// [history] window (the previous 24 h), valued at the flat feed-in tariff
67	  /// [feedInCt] (Einspeisevergütung). Unlike import, the feed-in rate is flat,
68	  /// so it doesn't need the spot curve and covers the full window.
69	  double? exportRevenueCents(EnergyHistoryData? history, double feedInCt) {
70	    if (history == null || history.points.isEmpty || feedInCt <= 0) return null;
71	    return history.gridExportKwh * feedInCt;
72	  }
73	
74	  /// [markupUeurPerKwh] (grid fees + levies + taxes, net) and [vatPercent] come
75	  /// from the controller's PricingConfig and turn the raw wholesale spot curve
76	  /// into the gross consumer price the user actually pays:
77	  ///   gross_ct = (spot_ct + markup_ct) × (1 + vat/100).
78	  factory EnergyPrices.fromProto(
79	    $proto.PriceCurve c, {
80	    int markupUeurPerKwh = 0,
81	    int vatPercent = 0,
82	  }) {
83	    final res = c.resolutionSeconds == 0 ? 3600 : c.resolutionSeconds;
84	    final start = c.startEpoch.toInt();
85	
86	    // Convert the stored unit to net ct/kWh. Canonical is µEUR/kWh (÷10000);
87	    // EUR/MWh (informational) is ÷10. Then add the tariff markup + VAT to reach
88	    // the gross consumer price.
89	    final divisor =
90	        c.unit == $enum.PriceUnit.PRICE_UNIT_EUR_PER_MWH ? 10.0 : 10000.0;
91	    final markupCt = markupUeurPerKwh / 10000.0;
92	    final vatMul = 1 + vatPercent / 100.0;
93	    final cts = c.prices
94	        .map((p) => (p / divisor + markupCt) * vatMul)
95	        .toList(growable: false);
96	
97	    final currency = c.currency.isNotEmpty ? c.currency : 'EUR';
98	    if (cts.isEmpty) {
99	      return EnergyPrices(
100	        points: const [],
101	        resolution: Duration(seconds: res),
102	        currency: currency,
103	        stale: c.stale,
104	        minCt: 0, maxCt: 0, avgCt: 0,
105	      );
106	    }
107	
108	    final minCt = cts.reduce((a, b) => a < b ? a : b);
109	    final maxCt = cts.reduce((a, b) => a > b ? a : b);
110	    final avgCt = cts.reduce((a, b) => a + b) / cts.length;
111	
112	    final points = <PricePoint>[
113	      for (var i = 0; i < cts.length; i++)
114	        PricePoint(
115	          time: DateTime.fromMillisecondsSinceEpoch((start + i * res) * 1000),
116	          ctPerKwh: cts[i],
117	        ),
118	    ];
119	
120	    return EnergyPrices(
121	      points: points,
122	      resolution: Duration(seconds: res),
123	      currency: currency,
124	      stale: c.stale,
125	      minCt: minCt,
126	      maxCt: maxCt,
127	      avgCt: avgCt,
128	    );
129	  }
130	}
