 * monotonic counter and are never reused, so a stale entry is inert); once the
 * table is full, later nodes fall back to accepting endpoint 1 only, which is
 * the primary application endpoint for every simple device. */
static struct { uint64_t node_id; uint16_t endpoint; } s_devtype_ep[FLUX_DEVICES_MAX];

/* True when @ep is allowed to set @node_id's device type. */
static bool devtype_ep_claim(uint64_t node_id, uint16_t ep)
{
    int slot = -1;
    for (size_t i = 0; i < FLUX_DEVICES_MAX; i++) {
        if (s_devtype_ep[i].node_id == node_id) {
            if (ep >= s_devtype_ep[i].endpoint) return false;  /* a lower one already won */
            s_devtype_ep[i].endpoint = ep;
            return true;
        }
        if (slot < 0 && s_devtype_ep[i].node_id == 0) slot = (int)i;
    }
    if (slot < 0) return ep == 1;
    s_devtype_ep[slot].node_id  = node_id;
    s_devtype_ep[slot].endpoint = ep;
    return true;
}

