/* Mark every session idle beyond the timeout for reclaim, then reap. Caller
 * holds s_lock. Returns how many were retired. */
static int retire_idle_locked(void)
{
    const int64_t now = esp_timer_get_time();
    int retired = 0;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        session_t *s = &s_sessions[i];
        if (!s->active) continue;
        const int64_t idle = now - s->last_rx_us;
        if (idle < SESSION_IDLE_TIMEOUT_US) continue;
        ESP_LOGW(TAG, "session %d idle for %llds — retiring",
                 i, (long long)(idle / 1000000));
        s->active = false;
        retired++;
    }
    if (retired) reap_dead();
    return retired;
}

/* Caller holds s_lock. Never returns NULL while any slot exists: when all are
 * taken the least-recently-active one is evicted, because refusing a valid
 * offer in favour of a session that may well be dead is the worse failure —
 * that is exactly how remote access became permanently unavailable. */
static session_t *alloc_session(void)
{
    for (int i = 0; i < MAX_SESSIONS; i++)
        if (!s_sessions[i].active && !s_sessions[i].ice) return &s_sessions[i];

    /* Nothing free — evict the least recently used. */
    int lru = -1;
    for (int i = 0; i < MAX_SESSIONS; i++)
        if (lru < 0 || s_sessions[i].last_rx_us < s_sessions[lru].last_rx_us) lru = i;
    if (lru < 0) return NULL;

    session_t *s = &s_sessions[lru];
    ESP_LOGW(TAG, "cap reached — evicting LRU session %d (idle %llds)",
             lru, (long long)((esp_timer_get_time() - s->last_rx_us) / 1000000));
    s->active = false;
    reap_dead();                       /* frees ice+bridge, leaves the slot free */
    return (!s->active && !s->ice) ? s : NULL;
}

